<?php require __DIR__.'/app/bootstrap.php';$m=one("SELECT m.*,s.business_name,s.id store_id,c.name category_name FROM menu_items m JOIN seller_applications s ON s.user_id=m.seller_id JOIN categories c ON c.id=m.category_id WHERE m.id=? AND ".live_sql('m')." AND s.status='approved' AND c.active=1",[(int)param('id')]);if(!$m)fail(404,t('This dish is no longer available. Explore the current menu instead.'));$title=$m['name'];require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="two-columns dish-detail"><img class="dish-hero" src="<?=e(image_url($m['photo_id']))?>" alt="<?=e($m['name'])?>"><section class="panel"><span class="heading-kicker"><?=e($m['category_name'])?></span><div class="dish-name-favourite"><h1><?=e($m['name'])?></h1><?=favourite_button('food',(int)$m['id'],'dish.php?id='.$m['id'],$m['name'])?></div><?php $foodRating=product_stats((int)$m['id']); ?><?=rating_html($foodRating['average'],$foodRating['count'])?><p><?=e(t('From'))?> <a href="<?=e(url('restaurant.php?id='.$m['store_id']))?>"><?=e($m['business_name'])?></a></p><strong class="dish-price"><?=e(t('Rs'))?> <?=number_format($m['price_paisa']/100,2)?></strong><p><?=nl2br(e($m['description']))?></p><h2><?=e(t('Ingredients & allergens'))?></h2><p><?=nl2br(e($m['ingredients']))?></p><p class="alert"><?=e(t('Available until'))?> <?=e(local_time(live_until($m)))?> · <?=e(cfg('timezone'))?></p><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form class="dish-add-cart"><?=csrf()?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$m['id']?>"><label for="quantity"><?=e(t('Quantity'))?></label><input id="quantity" type="number" name="quantity" min="1" max="20" value="1" required><button class="pill primary"><?=e(t('Add to Cart →'))?></button></form><p class="hint"><?=e(t('Choose pickup or delivery at checkout. Delivery charges are shown separately.'))?></p><a class="pill" href="<?=e(url())?>"><?=e(t('← Browse more dishes'))?></a></section></div></main><?php require ROOT.'/app/footer.php'; ?>
